-- ─── Transparency ────────────────────────────────────────────────────────────
local state_path = vim.fn.stdpath('data') .. '/wallpaper_state'

local function state_read()
  local f = io.open(state_path, 'r')
  if not f then
    return false
  end
  local v = f:read('*l')
  f:close()
  return v == 'transparent'
end

local function state_write(enable)
  local f = io.open(state_path, 'w')
  if not f then
    return
  end
  f:write(enable and 'transparent' or 'opaque')
  f:close()
end

M.transparent = state_read()

