local lualine_bg_cache = {}

local function apply_transparent(enable)
  for group, orig in pairs(transparent_bgs) do
    if enable then
      local no_bg = {}
      for k, v in pairs(orig) do
        if k ~= 'bg' and k ~= 'ctermbg' then
          no_bg[k] = v
        end
      end
      vim.api.nvim_set_hl(0, group, no_bg)
    else
      vim.api.nvim_set_hl(0, group, orig)
    end
  end

  local lualine_modes = {
    'normal',
    'insert',
    'visual',
    'replace',
    'command',
    'terminal',
    'inactive',
  }
  local lualine_sections = { 'a', 'b', 'c', 'x', 'y', 'z' }
  if enable then
    lualine_bg_cache = {}
    for _, mode in ipairs(lualine_modes) do
      for _, section in ipairs(lualine_sections) do
        local name = 'lualine_' .. section .. '_' .. mode
        local hl = vim.api.nvim_get_hl(0, { name = name })
        if hl and hl.bg then
          lualine_bg_cache[name] = vim.deepcopy(hl)
          local no_bg = {}
          for k, v in pairs(hl) do
            if k ~= 'bg' then
              no_bg[k] = v
            end
          end
          vim.api.nvim_set_hl(0, name, no_bg)
        end
      end
    end
  else
    for name, hl in pairs(lualine_bg_cache) do
      vim.api.nvim_set_hl(0, name, hl)
    end
    lualine_bg_cache = {}
  end
end

M.apply_transparent = apply_transparent

function M.set_transparent(enable)
  M.transparent = enable
  state_write(enable)
  apply_transparent(enable)
  vim.notify(
    'wallpaper: transparency ' .. (enable and 'on' or 'off'),
    vim.log.levels.INFO,
    { title = 'wallpaper' }
  )
end

function M.toggle_transparent()
  M.set_transparent(not M.transparent)
end

