  -- ─── Syntax-aware cursor ─────────────────────────────────────────────────
  local fallback_fg = c.fg

  local function resolve_fg(name)
    local seen, cur = {}, name
    for _ = 1, 8 do
      if seen[cur] then
        break
      end
      seen[cur] = true
      local ok, hl = pcall(vim.api.nvim_get_hl, 0, { name = cur, link = true })
      if not ok or not hl then
        break
      end
      if hl.fg then
        return string.format('#%06x', hl.fg)
      end
      if hl.link then
        cur = hl.link
      else
        break
      end
    end
  end

  local function capture_specificity(name)
    local n = 0
    for _ in name:gmatch('%.') do
      n = n + 1
    end
    return n
  end

  local function get_highest_priority_fg(buf, row, col)
    local candidates = {}
    local ok, marks = pcall(
      vim.api.nvim_buf_get_extmarks,
      buf,
      -1,
      { row, col },
      { row, col + 1 },
      { details = true, hl_name = true, overlap = true }
    )
    if ok then
      for _, mark in ipairs(marks) do
        local d = mark[4]
        if d and d.hl_group and d.priority then
          table.insert(
            candidates,
            { group = d.hl_group, priority = d.priority }
          )
        end
      end
    end
    local ts_ok, captures =
      pcall(vim.treesitter.get_captures_at_pos, buf, row, col)
    if ts_ok then
      for _, cap in ipairs(captures) do
        local n = '@' .. cap.capture
        local ln = n .. '.' .. (cap.lang or '')
        local sp = 100 + capture_specificity(cap.capture)
        table.insert(candidates, { group = ln, priority = sp + 0.5 })
        table.insert(candidates, { group = n, priority = sp })
      end
    end
    local syn_id = vim.fn.synID(row + 1, col + 1, true)
    if syn_id ~= 0 then
      local sn = vim.fn.synIDattr(vim.fn.synIDtrans(syn_id), 'name')
      if sn and sn ~= '' then
        table.insert(candidates, { group = sn, priority = 50 })
      end
    end
    table.sort(candidates, function(a, b)
      return a.priority > b.priority
    end)
    for _, cand in ipairs(candidates) do
      local fg = resolve_fg(cand.group)
      if fg then
        return fg
      end
    end
  end

  vim.o.updatetime = 120
  vim.api.nvim_create_autocmd({ 'CursorHold', 'CursorHoldI' }, {
    desc = 'Syntax-aware cursor colour',
    callback = function()
      local buf = vim.api.nvim_get_current_buf()
      local row, col = unpack(vim.api.nvim_win_get_cursor(0))
      local fg = get_highest_priority_fg(buf, row - 1, col)
      vim.api.nvim_set_hl(0, 'Cursor', { fg = c.bg, bg = fg or fallback_fg })
    end,
  })
end

vim.hl.priorities.semantic_tokens = 999

M.load()

if M.transparent then
  apply_transparent(true)
end

vim.api.nvim_create_autocmd('ColorScheme', {
  pattern = 'wallpaper',
  desc = 'wallpaper: restore transparency on reload',
  callback = function()
    if M.transparent then
      apply_transparent(true)
    end
  end,
})

vim.keymap.set('n', '<leader>tm', function()
  M.toggle_transparent()
end, { desc = 'wallpaper: toggle transparency', silent = true })

package.preload['dankula'] = function()
  return M
end
return M
